const code0 = "from fastapi import FastAPI\n\napp = FastAPI()\n\n@app.get(\"/\")\nasync def root():\n    return {\"message\": \"Hello World\"}\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"0.0.0.0\", port=8000)\n";
const code1 = "from fastapi import FastAPI, Request\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\n\napp = FastAPI()\n\n# Set static file location\napp.mount(\"/assets\", StaticFiles(directory=\"app/dist/assets\", html=True), name=\"static\")\n\n# Setup Jinja2 templates to serve index.html\ntemplates = Jinja2Templates(directory=\"app/dist\")\n\n@app.get(\"/\")\nasync def root(request: Request):\n    return templates.TemplateResponse(\"index.html\", {\"request\": request})\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"0.0.0.0\", port=8000)\n";
const code2 = "from fastapi import FastAPI, Request, WebSocket, WebSocketDisconnect\nfrom fastapi.staticfiles import StaticFiles\nfrom fastapi.templating import Jinja2Templates\nimport json\n\nmessages = []\n\napp = FastAPI()\n\n# Set static file location\napp.mount(\"/assets\", StaticFiles(directory=\"app/dist/assets\", html=True), name=\"static\")\n\n# Setup Jinja2 templates to serve index.html\ntemplates = Jinja2Templates(directory=\"app/dist\")\n\n# Serve index.html template from the root path\n@app.get(\"/\")\nasync def root(request: Request):\n    return templates.TemplateResponse(\"index.html\", {\"request\": request})\n\n# Create a websocket connection\n@app.websocket(\"/ws\")\nasync def websocket_endpoint(websocket: WebSocket):\n    await websocket.accept()\n    while True:\n        data = await websocket.receive_text()\n        message_data = json.loads(data)\n        if message_data['type'] == 'get_messages':\n            return_message = {'type': 'message_update', 'content': messages}\n            await websocket.send_text(json.dumps(return_message))\n\nif __name__ == \"__main__\":\n    import uvicorn\n    uvicorn.run(app, host=\"0.0.0.0\", port=8000)\n";
const code3 = "<script>\n  import ChatContent from \"./components/ChatContent.vue\";\n  import InputRow from \"./components/InputRow.vue\";\n  import ReconnectingWebSocket from \"reconnecting-websocket\";\n\n  export default {\n    name: \"App\",\n    components: {\n      ChatContent,\n      InputRow,\n    },\n    data() {\n      return {\n        messages: [],\n        socket: null,\n      };\n    },\n    mounted() {\n      this.socket = new ReconnectingWebSocket(\"ws://localhost:8000/ws\");\n      this.getMessages();\n    },\n    methods: {\n      getMessages() {},\n    },\n  };\n</" + "script>\n\n<template>\n  <div class=\"app\">\n    <div class=\"app-content\">\n      <ChatContent />\n      <InputRow />\n    </div>\n  </div>\n</template>\n\n<style scoped>\n  .app {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    height: 100vh;\n    width: 100vw;\n    margin: 0;\n    padding: 0;\n  }\n\n  .app-content {\n    display: flex;\n    flex-direction: column;\n    flex-grow: 1;\n    padding: 1rem;\n    width: 100%;\n    max-width: 1000px;\n    overflow: auto;\n  }\n</style>\n";
const code4 = "<script>\n  import ChatContent from \"./components/ChatContent.vue\";\n  import InputRow from \"./components/InputRow.vue\";\n  import ReconnectingWebSocket from \"reconnecting-websocket\";\n\n  export default {\n    name: \"App\",\n    components: {\n      ChatContent,\n      InputRow,\n    },\n    data() {\n      return {\n        messages: [],\n        socket: null,\n      };\n    },\n    mounted() {\n      this.socket = new ReconnectingWebSocket(\"ws://localhost:8000/ws\");\n      this.socket.onmessage = this.handleSocketMessage;\n      this.getMessages();\n    },\n    beforeDestroy() {\n      this.socket.close();\n    },\n    methods: {\n      handleSocketMessage(event) {\n        const data = JSON.parse(event.data);\n        console.log(data);\n        if (data.type === \"message_update\") {\n          this.messages = data.content;\n        }\n      },\n      getMessages() {\n        const newMessage = {\n          type: \"get_messages\",\n        };\n        this.sendSocketmessage(newMessage);\n      },\n      sendSocketmessage(message) {\n        this.socket.send(JSON.stringify(message));\n      },\n    },\n  };\n</" + "script>\n\n<!-- Existing template and style -->\n";
const code5 = "<!-- Existing script -->\n\n<template>\n  <div class=\"app\">\n    <div class=\"app-content\">\n      <ChatContent :messages=\"this.messages\" />\n      <InputRow :sendSocketMessage=\"this.sendSocketMessage\" />\n    </div>\n  </div>\n</template>\n\n<!-- Existing style -->\n";
const code6 = "<script>\n  import ChatBubble from \"./ChatBubble.vue\";\n\n  export default {\n    name: \"ChatContent\",\n    components: {\n      ChatBubble,\n    },\n    props: {\n      messages: {\n        type: Array,\n        required: true,\n      },\n    },\n  };\n</" + "script>\n\n<!-- Existing template and style -->\n";
const code7 = "<script>\n  export default {\n    name: \"InputRow\",\n    props: {\n      sendSocketMessage: {\n        type: Function,\n        required: true,\n      },\n    },\n    data() {\n      return {\n        messageContent: \"\",\n      };\n    },\n    methods: {\n      async sendMessage() {\n        if (this.messageContent.trim() !== \"\") {\n          const newMessage = {\n            type: \"new_message\",\n            content: this.messageContent,\n          };\n          this.sendSocketMessage(newMessage);\n          this.messageContent = \"\";\n        }\n      },\n    },\n  };\n</" + "script>\n\n<template>\n  <div class=\"input-row\">\n    <textarea\n      rows=\"3\"\n      v-model=\"this.messageContent\"\n      placeholder=\"Type a message\"\n      @keydown.enter=\"sendMessage\"\n    ></textarea>\n    <button @click=\"sendMessage\">Send</button>\n  </div>\n</template>\n\n<!-- Existing style -->\n";
const code8 = "# Create a websocket connection\n@app.websocket(\"/ws\")\nasync def websocket_endpoint(websocket: WebSocket):\n    await websocket.accept()\n    try:\n        while True:\n            data = await websocket.receive_text()\n            message_data = json.loads(data)\n            print(message_data)\n            if message_data['type'] == 'get_messages':\n                return_message = {'type': 'message_update', 'content': messages}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n            if message_data['type'] == 'new_message':\n                new_message = message_data['content']\n                messages.append({'role': 'user', 'content': new_message})\n                messages.append({'role': 'assistant', 'content': new_message})\n                return_message = {'type': 'message_update', 'content': messages}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n    except WebSocketDisconnect:\n        print(\"Client disconnected\")\n";
const code9 = "<script>\n  export default {\n    name: \"InputRow\",\n    props: {\n      sendSocketMessage: {\n        type: Function,\n        required: true,\n      },\n    },\n    data() {\n      return {\n        messageContent: \"\",\n      };\n    },\n    methods: {\n      async sendMessage() {\n        if (this.messageContent.trim() !== \"\") {\n          const newMessage = {\n            type: \"new_message\",\n            content: this.messageContent,\n          };\n          this.sendSocketMessage(newMessage);\n          this.messageContent = \"\";\n        }\n      },\n      async clearMessages() {\n        const newMessage = {\n          type: \"clear_messages\",\n        };\n        this.sendSocketMessage(newMessage);\n      },\n    },\n  };\n</" + "script>\n\n<template>\n  <div class=\"input-row\">\n    <button @click=\"clearMessages\" class=\"btn-clear\">Clear Chat</button>\n    <textarea\n      rows=\"3\"\n      v-model=\"this.messageContent\"\n      placeholder=\"Type a message\"\n      @keydown.enter=\"sendMessage\"\n    ></textarea>\n    <button @click=\"sendMessage\" class=\"btn-send\">Send</button>\n  </div>\n</template>\n\n<style scoped>\n  .input-row {\n    display: flex;\n    align-items: stretch;\n    background-color: #fdf0d7;\n    border-radius: 10px;\n    box-shadow: 0 0 10px rgba(0, 0, 0, 0.2);\n    padding: 10px;\n    width: 100%;\n  }\n\n  textarea {\n    flex-grow: 1;\n    margin: 0 10px;\n  }\n\n  .input-row button {\n    background-color: #f0e6fb;\n    border: none;\n    border-radius: 5px;\n    padding: 10px;\n    cursor: pointer;\n    color: #00000089;\n    box-shadow: 1px 2px 3px rgba(0, 0, 0, 0.25);\n    transition:\n      background-color 0.2s ease-in-out,\n      box-shadow 0.1s ease-in-out;\n  }\n\n  button:hover {\n    filter: brightness(0.9);\n  }\n\n  button:active {\n    box-shadow: none;\n  }\n\n  .input-row .btn-clear {\n    background-color: #f17b7b;\n  }\n</style>\n";
const code10 = "@app.websocket(\"/ws\")\nasync def websocket_endpoint(websocket: WebSocket):\n    await websocket.accept()\n    try:\n        while True:\n            data = await websocket.receive_text()\n            message_data = json.loads(data)\n            print(message_data)\n            if message_data['type'] == 'get_messages':\n                return_message = {'type': 'message_update', 'content': messages}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n            if message_data['type'] == 'new_message':\n                new_message = message_data['content']\n                messages.append({'role': 'user', 'content': new_message})\n                messages.append({'role': 'assistant', 'content': new_message})\n                return_message = {'type': 'message_update', 'content': messages}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n            if message_data['type'] == 'clear_messages':\n                messages.clear()\n                return_message = {'type': 'message_update', 'content': messages}\n                print(return_message)\n                await websocket.send_text(json.dumps(return_message))\n\n    except WebSocketDisconnect:\n        print(\"Client disconnected\")\n";
</script>

<template>
  <p>It can be daunting to get started on creating your own custom webapp, especially if you're not a web developer. There are lots of nice design tools out there, but you lose some of the granular control if you don't code it yourself. As someone who's not a web developer, I've found that Vue.js is a great framework to get started with. It's easy to learn, and has a lot of great documentation and community support. In this series, I'll be showing you how to build a chatbot using Vue.js, and how to integrate it with a back-end API that will be interacting with the GPT-3.5 model. As a cherry on top, we will look at how to store the messages in a MongoDB database, so that we can use them later for other uses.</p>
  <p>If you want to jump straight to the finished product, you can find it at the code repository here.</p>
  <GithubRepoCard repo="lancewilhelm/vue-chatbot" />
  <p>In this part we will be working up to <a href="https://github.com/lancewilhelm/vue-chatbot/tree/d27449b1b159f8c6488ef96d1f6671ea9f6b977b" target="_blank" rel="noopener noreferrer">this commit.</a></p>
  <hr />
  <p>If you missed part 1, you can find it in the first post: <RouterLink to="/blog/vue-chatbot1">Vue.js Chatbot - Part 1</RouterLink></p>
  <hr />
  <ProseHeading id="what-is-fastapi" :level="2">What is FastAPI?</ProseHeading>
  <p><a href="https://fastapi.tiangolo.com/" target="_blank" rel="noopener noreferrer">FastAPI</a> is a Python framework for building APIs. It is similar to <a href="https://flask.palletsprojects.com/en/3.0.x/" target="_blank" rel="noopener noreferrer">Flask</a>, but is asynchronous, which makes it nice for performing multiple tasks at once. It also has a lot of great documentation and community support, which makes it easy to learn. While in our end-case we may not need a back-end like FastAPI given that we will be making API calls to OpenAI's servers (all of which could be accomplished on the front end with JavaScript), it is a good exercise to learn how to build a back-end, and it will allow us to store the messages in a database for later use. This also sets up us for if we ever want to use a local large language model as the backbone of our chatbot.</p>
  <ProseHeading id="setting-up-the-back-end" :level="2">Setting up the Back-End</ProseHeading>
  <p>First, we need to install two dependencies to get FastAPI running. Run <code>pip install fastapi uvicorn</code> to install them. Next, we need to create a file to contain our server/API code. At the very root of your project, which is outside the <code>app/</code> folder from <RouterLink to="/blog/vue-chatbot1">part 1</RouterLink>, create a file <code>main.py</code> and add the following code:</p>
  <CodeBlock language="python" filename="main.py" :code="code0" />
  <p>Now, if you run <code>python main.py</code> in your terminal and following the link to the URL provided, you should see a python dictionary or JSON object with the key <code>message</code> and the value <code>Hello World</code>. Congratulations, you are now a back-end developer! 🎉</p>
  <ProseHeading id="serving-up-our-front-end" :level="2">Serving up our Front-End</ProseHeading>
  <p>OK, maybe not a back-end developer, but you are on your way! Now let's build our front-end and serve it up with the FastAPI backend server. First, navigate to your webapp directory, for me that is <code>app/</code>, and run <code>npm run build</code>. This will compile your website and place it in the <code>dist/</code> directory. Now, we can modify <code>main.py</code> to serve up our front-end. Replace the contents of <code>main.py</code> with the following:</p>
  <CodeBlock language="python" filename="main.py" :code="code1" />
  <p>You will need to install Jinja2 first with <code>pip install jinja2</code>. While we will not be taking advantage of Jinja templating in this project, serving the page with Jinja allows us to keep a simple GET route for the root, <code>/</code>. We also mounted our static files that we built, which are located at <code>app/dist/assets</code> so that the HTML file can access the actual page. Now, if you run <code>python main.py</code> and navigate to the URL provided, you should see all of your work from <RouterLink to="/blog/vue-chatbot1">part 1</RouterLink>!</p>
  <ProseHeading id="adding-a-websocket-connection" :level="2">Adding a Websocket Connection</ProseHeading>
  <p>Now that our page is being served by FastAPI, let's take advantage of its true purpose, which is to create an API. In our case, we are going to create a websocket connection that will allow us to send messages to the server and also allows the server to send us updates without us having to make a request. This is particularly useful in our case because we will be sending messages to the GPT-3.5 model, which can take a few seconds to respond. We don't want to have to wait for the response before we do anything else on the front-end.</p>
  <p>We are going to modify <code>main.py</code> again to add a websocket connection. Replace the contents of <code>main.py</code> with the following:</p>
  <CodeBlock language="python" filename="main.py" :code="code2" />
  <p>We added a new endpoint, <code>/ws</code>, which will be our websocket connection. We also added a list, <code>messages</code>, which will store all the messages that we send and receive from the GPT-3.5 model. Notice that our <code>websocket_endpoint()</code> function is an infinite while loop that is always waiting for a message to be sent to it. When it receives a message, it will check the type of message. In this first case, if <code>message_data['type']</code> is equal to <code>get_messages</code>, then it will send back a message with the type <code>message_update</code> and the content of the <code>messages</code> list. This will allow us to update the front end with the current list of messages. Using websockets in FastAPI requires the <code>websockets</code> package, so make sure you install it with <code>pip install websockets</code>.</p>
  <p>Now we need to modify our front end to establish the websocket connection with the back-end. First, let's modify <code>App.vue</code> in our <code>app/src/</code> directory. Replace the contents of <code>App.vue</code> with the following:</p>
  <CodeBlock language="html" filename="App.vue" :code="code3" />
  <p>Notice that the <code>&lt;script&gt;</code> tags changed from before as we are now adding the full complement of JavaScript for the app. Furthermore, we are taking advantage of the NPM package <a href="https://www.npmjs.com/package/reconnecting-websocket" target="_blank" rel="noopener noreferrer">reconnecting-websocket</a> to establish a websocket connection with the back-end. Be sure to install this in your <code>app/</code> directory with <code>npm install reconnecting-websocket</code>. Lastly, we add a few things to the exported object. We add a <code>data()</code> function that returns an object with two keys, <code>messages</code> and <code>socket</code>, which hold our messages received from the backend and the socket connection. Then, in <code>mounted()</code>, which is run when the page is loaded, we create the websocket connection with our backend and store it in <code>socket</code> from the <code>data()</code> function. Lastly, as a placeholder, we run <code>getMessages()</code> which will be used to get the messages from the backend.</p>
  <ProseHeading id="getting-messages-from-the-back-end" :level="2">Getting Messages from the Back-End</ProseHeading>
  <p>Now that we have a websocket connection, let's update the JavaScript in <code>App.vue</code> with the following:</p>
  <CodeBlock language="html" filename="App.vue" :code="code4" />
  <p>Here we added a few things. First, we added a handler in <code>mounted()</code>, which tells us what function to run when we receive a message from the back-end. In this case, we are running <code>handleSocketMessage()</code>, which will parse the message and run code depending on the message received. In our case, if a <code>message_update</code> is received the code will update <code>messages</code> with the received messages from the back-end. We also update our <code>getMessages()</code> function to send a message to the back-end to request the messages. Lastly, we add a <code>beforeDestroy()</code> function, which will close the websocket connection when the page is closed. This is important because we don't want to leave the connection open when we are not using it.</p>
  <p>If you open up the console on your browser (right click, inspect, then find the console) and refresh the page, you should see that we now are receiving an empty message list from the back-end!</p>
  <BlogImage eager image-path="/img/vue-chatbot/chatbot4.png" alt="Browser console showing an empty message list" caption="Console screenshot of the empty message list" width="600px" />
  <ProseHeading id="mimic-bot" :level="2">Mimic Bot</ProseHeading>
  <p>Now that we have a websocket connection, let's add a "bot" that will mimic the user. This will allow us to test the websocket connection and see how the messages are being sent and received. First, let's modify <code>App.vue</code> to pass the <code>messages</code> as a prop into the <code>ChatContent</code> component and the <code>sendSocketMessage()</code> into the <code>InputRow</code> component.</p>
  <CodeBlock language="html" filename="InputRow.vue" :code="code5" />
  <p>Next, we need to modify <code>ChatContent.vue</code> to accept the <code>messages</code> prop and display them. Modify the contents of <code>ChatContent.vue</code> with the following:</p>
  <CodeBlock language="html" filename="ChatContent.vue" :code="code6" />
  <p>Notice that now our messages are coming from a prop rather than from the result of <code>data()</code>. Next, we need to heavily modify the script in <code>InputRow.vue</code> to handle the sending of messages. Modify the contents of <code>InputRow.vue</code> with the following:</p>
  <CodeBlock language="html" filename="InputRow.vue" :code="code7" />
  <p>Here we added a <code>sendMessage()</code> function that will send a message to the back-end when the user clicks the send button or presses enter. We also added a <code>messageContent</code> variable to store the message that the user is typing. Notice that we are passing the <code>sendSocketMessage()</code> function as a prop, which is why we need to call it with <code>this.sendSocketMessage()</code>.</p>
  <p>One last thing we need to do is modify <code>main.py</code> in order to handle receiving new messages from the front-end. Modify the contents of the <code>websocket_endpoint()</code> function with the following:</p>
  <CodeBlock language="python" filename="main.py" :code="code8" />
  <p>Here we added a new <code>if</code> statement that will handle receiving a new message from the front-end. When a new message is received, it will append the message to the <code>messages</code> list twice, once for the user and once for the assistant. Then, it will send the updated <code>messages</code> list back to the front-end.</p>
  <p>Now, if you rebuild your webapp with <code>npm run build</code> in the <code>app/</code> directory and then run <code>python main.py</code> in the root directory, you should be able to send messages to the back-end and receive them back! You have your own mimic bot!</p>
  <BlogImage image-path="/img/vue-chatbot/chatbot5.png" alt="Chatbot conversation with a bot that repeats messages" caption="Mimic bot, engage!" width="600px" />
  <ProseHeading id="one-last-thing-before-stop-for-now" :level="2">One last thing before stop for now</ProseHeading>
  <p>Let's create a "clear chat" button that will allow us to clear the chat. As our app stands, you have to restart the back-end for the messages to disappear. We will need to add the button and a new function to <code>InputRow.vue</code> as well as modify <code>main.py</code> to handle the new message type. First, replace the contents of <code>InputRow.vue</code> with the following:</p>
  <CodeBlock language="html" filename="InputRow.vue" :code="code9" />
  <p>We added a button to clear the chat and a new function, <code>clearMessages()</code>, that will send a message to the back-end to clear the messages. We also added some styling to make the buttons look nice. Next, we need to modify <code>main.py</code> to handle the new message type. Replace the contents of the <code>websocket_endpoint()</code> function with the following:</p>
  <CodeBlock language="python" filename="main.py" :code="code10" />
  <p>There is now a third <code>if</code> statement that will handle the new message type. When a <code>clear_messages</code> message is received, it will clear the <code>messages</code> list and send the updated list back to the front-end.</p>
  <p>Now, if you rebuild your webapp with <code>npm run build</code> in the <code>app/</code> directory and then run <code>python main.py</code> in the root directory, you should be able to clear the chat!</p>
  <ProseHeading id="in-the-final-part-of-this-series" :level="2">In the final part of this series</ProseHeading>
  <p>We are going to integrate the GPT-3.5 model into our chatbot and store the messages in a MongoDB database. Stay tuned!</p>
</template>
